#include "h3/game.hpp"
#include <algorithm>
namespace h3 {
void Game::runScenarioEvents(){
 if(!imported())return;using J=nlohmann::json;const char*names[]={"red","blue","tan","green","orange","purple","teal","pink"};const char*resourcesKey[]={"gold","wood","ore","mercury","sulfur","crystal","gems"};std::string notices;
 auto&executed=scenarioRules["executedEvents"];if(!executed.is_object())executed=J::object();
 auto due=[&](const J&e){int first=e.value("day_of_first_occurence",0)+1,repeat=e.value("repeat_after_days",0);return day==first||(repeat>0&&day>first&&(day-first)%repeat==0);};
 auto applies=[&](const J&e,int owner){if(owner<0)return false;if(!e.value(owner==0?"applies_to_human":"applies_to_computer",1))return false;int human=scenarioRules.value("originalPlayer",0),original=owner==0?human:owner<=human?owner-1:owner;return !e.contains("affected_players")||e["affected_players"].value(names[original],false);};
 auto apply=[&](const J&e,int owner,const std::string&key){if(!due(e)||!applies(e,owner)||executed.value(key,0)==day)return false;executed[key]=day;auto&bank=owner==0?resources:playerResources[owner];if(e.contains("resources"))for(int r=0;r<ResourceCount;++r)bank[r]=int(std::clamp<int64_t>(int64_t(bank[r])+e["resources"].value(resourcesKey[r],0),0,1000000000));if(owner==0){auto text=e.value("message",std::string{});if(!text.empty()){recordStory(e.value("name",std::string("地图事件")),text);message(text);if(!notices.empty())notices+="\n\n";notices+=text;}}return true;};
 int index=0;for(const auto&e:scenarioRules["timedEvents"]){for(int owner=0;owner<8;++owner){bool alive=std::any_of(heroes.begin(),heroes.end(),[&](auto&p){return p.second.owner==owner;})||std::any_of(objects.begin(),objects.end(),[&](auto&o){return o.type==ObjectType::Town&&o.owner==owner;});if(alive)apply(e,owner,"world:"+std::to_string(index)+":"+std::to_string(owner));}++index;}
 const std::pair<const char*,int> buildings[]={{"village_hall",VillageHall},{"town_hall",TownHall},{"city_hall",CityHall},{"capitol",Capitol},{"fort",Fort},{"citadel",Citadel},{"castle",Castle},{"tavern",Tavern},{"marketplace",Marketplace},{"blacksmith",Blacksmith},{"resource_silo",ResourceSilo},{"shipyard",Shipyard},{"mage_guild_1",MageGuild},{"mage_guild_2",MageGuild2},{"mage_guild_3",MageGuild3},{"mage_guild_4",MageGuild4},{"mage_guild_5",MageGuild5},{"special_building_1",Special1},{"special_building_2",Special2},{"special_building_3",Special3},{"special_building_4",Special4}};
 for(const auto&o:objects)if(o.type==ObjectType::Town&&o.owner>=0&&settlements.contains(o.id)){int eventIndex=0;for(const auto&e:o.properties.value("events",J::array())){bool triggered=apply(e,o.owner,"town:"+std::to_string(o.id)+":"+std::to_string(eventIndex++));if(!triggered)continue;auto&t=o.id==activeTownId?town:settlements[o.id];if(e.contains("buildings")){const auto&b=e["buildings"];for(auto[key,id]:buildings)if(b.value(key,false))t.built[id]=true;for(int tier=0;tier<7;++tier){if(b.value("dwelling_"+std::to_string(tier+1),false))t.built[Guardhouse+tier]=true;if(b.value("dwelling_"+std::to_string(tier+1)+"u",false))t.built[UpGuardhouse+tier]=true;}}
  if(e.contains("creatures"))for(int tier=0;tier<7&&tier<int(e["creatures"].size());++tier)t.pool[tier]=std::clamp(t.pool[tier]+e["creatures"][tier].get<int>(),0,MaxArmyStack);settlements[o.id]=t;}}
 if(!notices.empty())adventureVisit_=AdventureVisit{ObjectType::Site,"第 "+std::to_string(day)+" 天 · 地图事件",notices};
}
}
